package net.civeira.phylax.feature.observe.observedprobe.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbeRef;

public interface ObservedProbeQueryRepositoryGateway {

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The items that would be returned by the query
   */
  long count(ObservedProbeFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  boolean exists(String uid, Optional<ObservedProbeFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  Optional<ObservedProbe> find(ObservedProbeFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  List<ObservedProbe> list(ObservedProbeFilter filter);

  /**
   * Retrieve full data for a reference.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param reference a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  ObservedProbe resolve(ObservedProbeRef reference);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  Optional<ObservedProbe> retrieve(String uid, Optional<ObservedProbeFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @param cursor a cursor to order and skip
   * @return The slide with some values
   */
  Slider<ObservedProbe> slide(ObservedProbeFilter filter, ObservedProbeCursor cursor);
}
